{
  "findings": [
    {
      "check_id": "CKV_GCP_106",
      "title": "Ensure Google compute firewall ingress does not allow unrestricted http port 80 access",
      "resource": "google_compute_firewall.allow_http",
      "severity": "MEDIUM",
      "explanation": "The firewall rule allows unrestricted access to port 80 from any source IP address (0.0.0.0/0)."
    }
  ],
  "patched_code": "resource "google_compute_firewall" "allow_http" {
  name    = "digital-library-content-management-platform-firewall-http"
  network = google_compute_network.digital_library_vpc.name
  allow {
    protocol = "tcp"
    ports    = ["443"]
  }
  allow {
    protocol = "tcp"
    ports    = ["80"]
    source_ranges = ["10.0.0.0/8"]
  }
  target_tags   = ["http-server"]
}",
  "fix_summary": "Restrict port 80 access to a specific IP range (10.0.0.0/8) while keeping port 443 open to all."
}
